namespace ghidra.pcodeCPort.slghpatexpress;

using ghidra.sleigh.grammar;

public abstract class ValExpressEquation : PatternEquation {

	protected PatternValue lhs;
	protected PatternExpression rhs;

	ValExpressEquation( Location location, PatternValue l, PatternExpression r ) : base(location)
    {
		(lhs = l).layClaim();
		(rhs = r).layClaim();
	}

	/* @Override */
	public bool resolveOperandLeft(OperandResolve state) {
		state.cur_rightmost = -1;
		if (getTokenPattern().getLeftEllipsis()||getTokenPattern().getRightEllipsis())
			state.size = -1;
		else
			state.size = getTokenPattern().getMinimumLength();
		return true;
	}

	/* @Override */
    protected void dispose() {
		PatternExpression.release( lhs );
		PatternExpression.release( rhs );
	}

}
